class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.previous_closes = {}
        self.spy_comparisons = RollingWindow[bool](2)
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to update even if another ticker is
        # absent and consequently prevents strategy evaluation on this bar.
        if "SPY" in bars:
            spy_close = bars["SPY"].close
            self.spy_sma.update(self.time, spy_close)
            if self.spy_sma.is_ready:
                self.spy_comparisons.add(spy_close > self.spy_sma.current.value)

        if "AAPL" in bars:
            aapl_close = bars["AAPL"].close
            self.aapl_rsi.update(self.time, aapl_close)
            previous = self.previous_closes.get("AAPL")
            if previous is not None and aapl_close < previous:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close

        if len(bars) != len(self.symbols):
            return
        if not self.spy_comparisons.is_ready or not self.aapl_rsi.is_ready:
            return

        spy_crossed_above = (
            not self.spy_comparisons[1] and self.spy_comparisons[0]
        )
        spy_crossed_below = (
            self.spy_comparisons[1] and not self.spy_comparisons[0]
        )

        # Evaluate every sell before evaluating either strategy's buy.
        if self.spy_lot > 0 and spy_crossed_below:
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            close = bars["AAPL"].close
            if self.portfolio.cash >= 20_000:
                quantity = int(20_000 // close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

