class ParallelDailyStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG")
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]
        self.spy_average = self.SMA(
            self.spy, self.MOVING_AVERAGE_PERIOD, Resolution.Daily
        )
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_closes = {}
        self.previous_spy_above_average = None
        self.aapl_red_streak = 0
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(self.MOVING_AVERAGE_PERIOD + 1, Resolution.Daily)

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        self._update_continuous_state(bars)

        if self.IsWarmingUp or len(bars) != len(self.symbols):
            self._record_spy_average_relation(bars)
            return
        if not self.spy_average.IsReady or not self.aapl_rsi.IsReady:
            self._record_spy_average_relation(bars)
            return

        spy_close = float(bars["SPY"].Close)
        spy_above_average = spy_close > float(self.spy_average.Current.Value)

        # All exits are evaluated before any entries.
        if (
            self.strategy_a_shares > 0
            and self.previous_spy_above_average is True
            and not spy_above_average
        ):
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if (
            self.strategy_a_shares == 0
            and self.previous_spy_above_average is False
            and spy_above_average
        ):
            quantity = int(
                (float(self.Portfolio.TotalPortfolioValue) * 0.40) // spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if float(self.Portfolio.Cash) >= cash_to_invest:
                quantity = int(cash_to_invest // float(bars["AAPL"].Close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity

        self.previous_spy_above_average = spy_above_average

    def _update_continuous_state(self, bars):
        for ticker, bar in bars.items():
            close = float(bar.Close)
            previous_close = self.previous_closes.get(ticker)

            if ticker == "AAPL" and previous_close is not None:
                if close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_closes[ticker] = close

    def _record_spy_average_relation(self, bars):
        if "SPY" in bars and self.spy_average.IsReady:
            self.previous_spy_above_average = (
                float(bars["SPY"].Close) > float(self.spy_average.Current.Value)
            )

