class ParallelSpyAaplStrategies(QCAlgorithm):
    MA_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_closes = RollingWindow[float](self.MA_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.pending_orders = {}

    def OnData(self, data: Slice):
        all_bars_present = all(symbol in data.Bars for symbol in self.symbols.values())
        spy_bar = data.Bars.get(self.symbols["SPY"])
        aapl_bar = data.Bars.get(self.symbols["AAPL"])

        if spy_bar is None and aapl_bar is None:
            return

        if spy_bar is None:
            self._update_aapl_state(data.Time, float(aapl_bar.Close))
            return
        if aapl_bar is None:
            self._update_spy_state(float(spy_bar.Close))
            return

        spy_close = float(spy_bar.Close)
        aapl_close = float(aapl_bar.Close)

        if self.previous_aapl_close is not None:
            if aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.spy_closes.Add(spy_close)
        self.aapl_rsi.Update(data.Time, aapl_close)

        spy_average = None
        if self.spy_closes.IsReady:
            spy_average = sum(self.spy_closes[i] for i in range(self.MA_PERIOD)) / self.MA_PERIOD

        if not all_bars_present:
            self.previous_spy_close = spy_close
            self.previous_spy_average = spy_average
            self.previous_aapl_close = aapl_close
            return

        # Sells are evaluated before buys.
        if (
            self.strategy_a_shares > 0
            and self.previous_spy_average is not None
            and self.previous_spy_close is not None
            and self.previous_spy_close >= self.previous_spy_average
            and spy_close < spy_average
        ):
            self._submit_lot_order("A", self.symbols["SPY"], -self.strategy_a_shares)

        if self.strategy_b_shares > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self._submit_lot_order("B", self.symbols["AAPL"], -self.strategy_b_shares)

        if (
            self.strategy_a_shares == 0
            and not self._has_pending_order("A")
            and self.previous_spy_average is not None
            and self.previous_spy_close is not None
            and self.previous_spy_close <= self.previous_spy_average
            and spy_close > spy_average
        ):
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self._submit_lot_order("A", self.symbols["SPY"], quantity)

        if (
            self.strategy_b_shares == 0
            and not self._has_pending_order("B")
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20_000
        ):
            quantity = int(20_000 // aapl_close)
            if quantity > 0:
                self._submit_lot_order("B", self.symbols["AAPL"], quantity)

        self.previous_spy_close = spy_close
        self.previous_spy_average = spy_average
        self.previous_aapl_close = aapl_close

    def _update_spy_state(self, close):
        self.spy_closes.Add(close)
        average = None
        if self.spy_closes.IsReady:
            average = sum(self.spy_closes[i] for i in range(self.MA_PERIOD)) / self.MA_PERIOD
        self.previous_spy_close = close
        self.previous_spy_average = average

    def _update_aapl_state(self, time, close):
        if self.previous_aapl_close is not None and close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0
        self.aapl_rsi.Update(time, close)
        self.previous_aapl_close = close

    def _submit_lot_order(self, strategy, symbol, quantity):
        if quantity == 0 or self._has_pending_order(strategy):
            return
        ticket = self.MarketOrder(symbol, quantity, False, strategy)
        self.pending_orders[ticket.OrderId] = strategy

    def _has_pending_order(self, strategy):
        return strategy in self.pending_orders.values()

    def OnOrderEvent(self, order_event: OrderEvent):
        strategy = self.pending_orders.get(order_event.OrderId)
        if strategy is None:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if strategy == "A":
                self.strategy_a_shares += int(order_event.FillQuantity)
            else:
                self.strategy_b_shares += int(order_event.FillQuantity)

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            del self.pending_orders[order_event.OrderId]

