class ParallelSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_close = {}
        self.aapl_red_streak = 0
        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.lot_quantity = {"A": 0, "B": 0}
        self.pending_order = {"A": None, "B": None}
        self.order_owner = {}

    def OnData(self, data: Slice):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if bars.ContainsKey(spy):
            spy_bar = bars[spy]
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)

        if bars.ContainsKey(aapl):
            aapl_bar = bars[aapl]
            prior_aapl_close = self.previous_close.get(aapl)
            if prior_aapl_close is None or aapl_bar.Close >= prior_aapl_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        complete_day = all(bars.ContainsKey(symbol) for symbol in self.symbols.values())

        if complete_day:
            self._synchronize_lots()

            spy_close = bars[spy].Close
            current_spy_sma = self.spy_sma.Current.Value if self.spy_sma.IsReady else None

            spy_crosses_above = (
                current_spy_sma is not None
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_close > current_spy_sma
            )
            spy_crosses_below = (
                current_spy_sma is not None
                and self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and spy_close < current_spy_sma
            )

            if self.lot_quantity["A"] > 0:
                if spy_crosses_below and self.pending_order["A"] is None:
                    self._submit_order("A", spy, -self.lot_quantity["A"])
            elif spy_crosses_above and self.pending_order["A"] is None:
                quantity = self.CalculateOrderQuantity(spy, 0.40)
                if quantity > 0:
                    self._submit_order("A", spy, quantity)

            if self.lot_quantity["B"] > 0:
                if (
                    self.aapl_rsi.IsReady
                    and self.aapl_rsi.Current.Value > 60
                    and self.pending_order["B"] is None
                ):
                    self._submit_order("B", aapl, -self.lot_quantity["B"])
            elif (
                self.aapl_red_streak >= 3
                and self.aapl_rsi.IsReady
                and self.Portfolio.Cash >= 20_000
                and self.pending_order["B"] is None
            ):
                quantity = floor(20_000 / bars[aapl].Close)
                if quantity > 0:
                    self._submit_order("B", aapl, quantity)

        if bars.ContainsKey(spy) and self.spy_sma.IsReady:
            self.previous_spy_close = bars[spy].Close
            self.previous_spy_sma = self.spy_sma.Current.Value

        for symbol in self.symbols.values():
            if bars.ContainsKey(symbol):
                self.previous_close[symbol] = bars[symbol].Close

    def _submit_order(self, owner, symbol, quantity):
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_order[owner] = ticket.OrderId
        self.order_owner[ticket.OrderId] = owner

    def _synchronize_lots(self):
        self.lot_quantity["A"] = max(0, int(self.Portfolio[self.symbols["SPY"]].Quantity))
        self.lot_quantity["B"] = max(0, int(self.Portfolio[self.symbols["AAPL"]].Quantity))

    def OnOrderEvent(self, order_event: OrderEvent):
        owner = self.order_owner.get(order_event.OrderId)
        if owner is None:
            return

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            self.pending_order[owner] = None
            del self.order_owner[order_event.OrderId]

        if order_event.Status == OrderStatus.Filled:
            self._synchronize_lots()

