class IndependentSlotsStrategy(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](self.MOVING_AVERAGE_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            self.RSI_PERIOD, MovingAverageType.Wilders
        )

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def OnData(self, data: Slice):
        bars = data.Bars

        # Market state is updated whenever its own data is present, even on a
        # day on which another subscription is missing.
        if bars.ContainsKey(self.symbols["SPY"]):
            self.spy_closes.Add(float(bars[self.symbols["SPY"]].Close))

        if bars.ContainsKey(self.symbols["AAPL"]):
            aapl_bar = bars[self.symbols["AAPL"]]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_crossed_above = False
        spy_crossed_below = False
        if self.spy_closes.IsReady:
            today_close = self.spy_closes[0]
            yesterday_close = self.spy_closes[1]
            today_average = sum(self.spy_closes[i] for i in range(
                self.MOVING_AVERAGE_PERIOD
            )) / self.MOVING_AVERAGE_PERIOD
            yesterday_average = sum(self.spy_closes[i] for i in range(
                1, self.MOVING_AVERAGE_PERIOD + 1
            )) / self.MOVING_AVERAGE_PERIOD
            spy_crossed_above = (
                yesterday_close <= yesterday_average
                and today_close > today_average
            )
            spy_crossed_below = (
                yesterday_close >= yesterday_average
                and today_close < today_average
            )

        # Evaluate every sell before any buy.
        if self.strategy_a_quantity > 0 and spy_crossed_below:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_quantity)
            self.strategy_a_quantity = 0

        if (
            self.strategy_b_quantity > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if self.strategy_a_quantity == 0 and spy_crossed_above:
