class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=20)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0
        self.pending_orders = {}
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def OnData(self, data):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]
            else:
                complete_slice = False

        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(data.Time, aapl_close)

        spy_average = None
        spy_crosses_above = False
        spy_crosses_below = False
        if "SPY" in bars and len(self.spy_closes) == self.spy_closes.maxlen:
            spy_close = float(bars["SPY"].Close)
            spy_average = sum(self.spy_closes) / len(self.spy_closes)
            if self.previous_spy_close is not None and self.previous_spy_average is not None:
                spy_crosses_above = (
                    self.previous_spy_close <= self.previous_spy_average
                    and spy_close > spy_average
                )
                spy_crosses_below = (
                    self.previous_spy_close >= self.previous_spy_average
                    and spy_close < spy_average
                )

        if complete_slice:
            # All sell rules are evaluated before either strategy's buy rule.
            if (
                self.strategy_a_quantity > 0
                and not self.strategy_a_pending
                and spy_crosses_below
            ):
                self._submit_order("A", -self.strategy_a_quantity)

            if (
                self.strategy_b_quantity > 0
                and not self.strategy_b_pending
                and self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > 60
            ):
                self._submit_order("B", -self.strategy_b_quantity)

            if (
                self.strategy_a_quantity == 0
                and not self.strategy_a_pending
                and spy_crosses_above
            ):
                quantity = floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue)
                    / float(bars["SPY"].Close)
                )
                if quantity > 0:
                    self._submit_order("A", quantity)

            if (
                self.strategy_b_quantity == 0
                and not self.strategy_b_pending
                and self.aapl_red_streak >= 3
                and float(self.Portfolio.CashBook["USD"].Amount) >= 20_000
            ):
                quantity = floor(20_000 / float(bars["AAPL"].Close))
                if quantity > 0:
                    self._submit_order("B", quantity)

        if spy_average is not None:
            self.previous_spy_close = float(bars["SPY"].Close)
            self.previous_spy_average = spy_average

    def _submit_order(self, strategy, quantity):
        symbol = self.symbols["SPY"] if strategy == "A" else self.symbols["AAPL"]
        ticket = self.MarketOrder(symbol, quantity, False, "Strategy " + strategy)
        self.pending_orders[ticket.OrderId] = strategy
        if strategy == "A":
            self.strategy_a_pending = True
        else:
            self.strategy_b_pending = True

    def OnOrderEvent(self, order_event):
        if order_event.OrderId not in self.pending_orders:
            return

        strategy = self.pending_orders[order_event.OrderId]
        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            fill_quantity = int(order_event.FillQuantity)
            if strategy == "A":
                self.strategy_a_quantity += fill_quantity
            else:
                self.strategy_b_quantity += fill_quantity

        if order_event.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            del self.pending_orders[order_event.OrderId]
            if strategy == "A":
                self.strategy_a_pending = False
            else:
                self.strategy_b_pending = False

