        if average is None or self.previous_spy_average is None:
            return

        symbol = self.symbols["SPY"]
        if self.transactions.get_open_orders(symbol):
            return

        close = float(bar.close)
        quantity = self.portfolio[symbol].quantity
        crossed_below = (
            self.previous_spy_close >= self.previous_spy_average
            and close < average
        )
        crossed_above = (
            self.previous_spy_close <= self.previous_spy_average
            and close > average
        )

        if quantity != 0:
            if crossed_below:
                self.market_order(symbol, -quantity)
        elif crossed_above:
            order_quantity = self.calculate_order_quantity(symbol, 0.40)
            if order_quantity != 0:
                self.market_order(symbol, order_quantity)

    def _evaluate_aapl(self, bar: TradeBar):
        if not self.aapl_rsi.is_ready:
            return

        symbol = self.symbols["AAPL"]
        if self.transactions.get_open_orders(symbol):
            return

        quantity = self.portfolio[symbol].quantity
        if quantity != 0:
            if self.aapl_rsi.current.value > 60:
                self.market_order(symbol, -quantity)
            return

        cash = float(self.portfolio.cash)
        if self.aapl_red_streak >= 3 and cash >= 20_000:
            order_quantity = floor(20_000 / float(bar.close))
            if order_quantity > 0:
                self.market_order(symbol, order_quantity)

