        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.moving_average_period = 20
        self.closes = {ticker: [] for ticker in self.symbols}
        self.previous_spy_average = None
        self.aapl_red_streak = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        previous_closes = {
            ticker: values[-1] if values else None
            for ticker, values in self.closes.items()
        }

        previous_aapl_close = previous_closes["AAPL"]
        aapl_close = bars["AAPL"].Close
        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = aapl_close - previous_aapl_close
            gain = max(change, 0)
            loss = max(-change, 0)
            completed_changes = len(self.closes["AAPL"])
            if completed_changes == 14:
                changes = [
                    self.closes["AAPL"][i] - self.closes["AAPL"][i - 1]
                    for i in range(1, 14)
                ]
                changes.append(change)
                self.aapl_average_gain = sum(max(value, 0) for value in changes) / 14
                self.aapl_average_loss = sum(max(-value, 0) for value in changes) / 14
            elif completed_changes > 14:
                self.aapl_average_gain = (self.aapl_average_gain * 13 + gain) / 14
                self.aapl_average_loss = (self.aapl_average_loss * 13 + loss) / 14

        for ticker, bar in bars.items():
            self.closes[ticker].append(bar.Close)

        spy_values = self.closes["SPY"]
        spy_average = None
        if len(spy_values) >= self.moving_average_period:
            spy_average = sum(spy_values[-self.moving_average_period:]) / self.moving_average_period

        rsi = None
        if self.aapl_average_gain is not None:
            if self.aapl_average_loss == 0:
                rsi = 100
            else:
                relative_strength = self.aapl_average_gain / self.aapl_average_loss
                rsi = 100 - 100 / (1 + relative_strength)

        fully_formed = (
            self.previous_spy_average is not None
            and spy_average is not None
            and rsi is not None
        )
        if fully_formed:
            spy_close = bars["SPY"].Close
            previous_spy_close = previous_closes["SPY"]

            spy_crossed_below = (
                previous_spy_close >= self.previous_spy_average
                and spy_close < spy_average
            )
            if self.spy_lot > 0 and spy_crossed_below:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot > 0 and rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

            spy_crossed_above = (
                previous_spy_close <= self.previous_spy_average
                and spy_close > spy_average
            )
            if self.spy_lot == 0 and spy_crossed_above:
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                cash_amount = 20_000
                if self.Portfolio.Cash >= cash_amount:
                    quantity = int(cash_amount // aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.aapl_lot = quantity

        self.previous_spy_average = spy_average

