class IndependentSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD + 1)
        self.aapl_closes = deque(maxlen=self.RSI_PERIOD + 1)

        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        self.spy_closes.append(spy_close)
        self._update_aapl_rsi(aapl_close)
        self.aapl_closes.append(aapl_close)

        if not self._all_state_ready():
            return

        spy_crossed_above, spy_crossed_below = self._spy_crosses()
        aapl_red_for_three_days = self._aapl_red_for_three_days()

        # Every strategy evaluates its sell before any possible buy.
        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi > 60.0:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            shares = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and aapl_red_for_three_days:
            cash_to_invest = 20_000.0
            if float(self.Portfolio.Cash) >= cash_to_invest:
                shares = floor(cash_to_invest / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

    def _all_state_ready(self):
        return (
            len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD + 1
            and len(self.aapl_closes) == self.RSI_PERIOD + 1
            and self.aapl_rsi is not None
        )

    def _spy_crosses(self):
        closes = list(self.spy_closes)
        yesterday_close = closes[-2]
        today_close = closes[-1]
        yesterday_average = sum(closes[:-1]) / self.MOVING_AVERAGE_PERIOD
        today_average = sum(closes[1:]) / self.MOVING_AVERAGE_PERIOD
        crossed_above = yesterday_close <= yesterday_average and today_close > today_average
        crossed_below = yesterday_close >= yesterday_average and today_close < today_average
        return crossed_above, crossed_below

    def _aapl_red_for_three_days(self):
        closes = list(self.aapl_closes)
        return closes[-1] < closes[-2] < closes[-3] < closes[-4]

    def _update_aapl_rsi(self, close):
        if not self.aapl_closes:
            return

        change = close - self.aapl_closes[-1]
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.rsi_average_gain is None:
            if len(self.aapl_closes) < self.RSI_PERIOD:
                return
            prior_closes = list(self.aapl_closes)
            changes = [
                prior_closes[index] - prior_closes[index - 1]
                for index in range(1, len(prior_closes))
            ]
            gains = [max(value, 0.0) for value in changes] + [gain]
            losses = [max(-value, 0.0) for value in changes] + [loss]
            self.rsi_average_gain = sum(gains) / self.RSI_PERIOD
            self.rsi_average_loss = sum(losses) / self.RSI_PERIOD
        else:
            period = self.RSI_PERIOD
            self.rsi_average_gain = ((period - 1) * self.rsi_average_gain + gain) / period
            self.rsi_average_loss = ((period - 1) * self.rsi_average_loss + loss) / period

        if self.rsi_average_loss == 0.0:
            self.aapl_rsi = 100.0 if self.rsi_average_gain > 0.0 else 50.0
        else:
            relative_strength = self.rsi_average_gain / self.rsi_average_loss
            self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

