class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with privately tracked lots."""

    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.previous_spy_relation = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to consume whatever data is available,
        # even when a missing subscription prevents all rules from being evaluated.
        spy_relation = None
        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_average = sum(self.spy_closes) / self.MOVING_AVERAGE_PERIOD
                spy_relation = spy_close - spy_average

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        complete_day = len(bars) == len(self.symbols)
        spy_cross_ready = (
            spy_relation is not None and self.previous_spy_relation is not None
        )

        if complete_day:
            # Sells are evaluated before buys. Each ticker is owned by only its
            # corresponding strategy, so these quantities are the private lots.
            if self.spy_lot > 0 and spy_cross_ready:
                crossed_below = (
                    self.previous_spy_relation >= 0 and spy_relation < 0
                )
                if crossed_below:
                    self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                    self.spy_lot = 0

            if (
                self.aapl_lot > 0
                and self.aapl_rsi.IsReady
                and self.aapl_rsi.Current.Value > 60
            ):
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

            if self.spy_lot == 0 and spy_cross_ready:
                crossed_above = (
                    self.previous_spy_relation <= 0 and spy_relation > 0
                )
                if crossed_above:
                    quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["SPY"], quantity)
                        self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_rsi.IsReady:
                if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                    quantity = floor(20_000 / float(bars["AAPL"].Close))
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.aapl_lot = quantity

        # Preserve the latest fully formed per-ticker value for the next cross,
        # including on dates where another subscribed ticker was missing.
        if spy_relation is not None:
            self.previous_spy_relation = spy_relation

