class ParallelTwoSlotStrategy(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 50

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(self.MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        # Each strategy accounts for only the shares purchased by that strategy.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = data.Bars
        available = {ticker: symbol in bars for ticker, symbol in self.symbols.items()}

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        spy_close = None
        spy_sma_value = None
        if available["SPY"]:
            spy_bar = bars[spy]
            spy_close = float(spy_bar.Close)
            self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
            if self.spy_sma.IsReady:
                spy_sma_value = float(self.spy_sma.Current.Value)

        if available["AAPL"]:
            aapl_bar = bars[aapl]
            aapl_close = float(aapl_bar.Close)
            prior_aapl_close = self.previous_closes.get(aapl)
            if prior_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < prior_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        # A partial slice still advances each ticker's market-state quantities, but
        # no strategy rule is evaluated unless every subscribed bar is present.
        if not all(available.values()):
            self._save_previous_values(bars, spy_close, spy_sma_value)
            return

        aapl_close = float(bars[aapl].Close)
        indicators_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and spy in self.previous_closes
            and aapl in self.previous_closes
            and self.previous_spy_sma is not None
        )

        if indicators_ready:
            previous_spy_close = self.previous_closes[spy]
            spy_crossed_below = (
                previous_spy_close >= self.previous_spy_sma
                and spy_close < spy_sma_value
            )
            spy_crossed_above = (
                previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma_value
            )

            # Sells are evaluated before buys.
            if self.strategy_a_shares > 0 and spy_crossed_below:
                self.MarketOrder(spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if self.strategy_b_shares > 0 and float(self.aapl_rsi.Current.Value) > 60:
                self.MarketOrder(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and spy_crossed_above:
                shares = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
                if shares > 0:
                    self.MarketOrder(spy, shares)
                    self.strategy_a_shares = shares

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                cash_to_invest = 20_000
                if float(self.Portfolio.Cash) >= cash_to_invest:
                    shares = floor(cash_to_invest / aapl_close)
                    if shares > 0:
                        self.MarketOrder(aapl, shares)
                        self.strategy_b_shares = shares

        self._save_previous_values(bars, spy_close, spy_sma_value)

    def _save_previous_values(self, bars, spy_close, spy_sma_value):
        for symbol in self.symbols.values():
            if symbol in bars:
                self.previous_closes[symbol] = float(bars[symbol].Close)
        if spy_close is not None and spy_sma_value is not None:
            self.previous_spy_sma = spy_sma_value

