class ParallelMovingAverageAndRsiAlgorithm(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD + 1)
        self.aapl_closes = deque(maxlen=2)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_red_streak = 0
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data):
        self._apply_splits(data)

        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if bars.ContainsKey(spy):
            self.spy_closes.append(float(bars[spy].Close))

        if bars.ContainsKey(aapl):
            aapl_close = float(bars[aapl].Close)
            if self.aapl_closes:
                if aapl_close < self.aapl_closes[-1]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.append(aapl_close)
            self.aapl_rsi.Update(bars[aapl].EndTime, aapl_close)

        if any(not bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        spy_ready = len(self.spy_closes) == self.spy_closes.maxlen
        aapl_ready = self.aapl_rsi.IsReady
        if not (spy_ready and aapl_ready):
            return

        spy_close = self.spy_closes[-1]
        spy_previous_close = self.spy_closes[-2]
        spy_average = sum(list(self.spy_closes)[-self.MOVING_AVERAGE_PERIOD:]) / self.MOVING_AVERAGE_PERIOD
        spy_previous_average = sum(list(self.spy_closes)[:-1]) / self.MOVING_AVERAGE_PERIOD

        aapl_close = self.aapl_closes[-1]

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and spy_previous_close >= spy_previous_average and spy_close < spy_average:
            self.MarketOrder(spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and float(self.aapl_rsi.Current.Value) > 60.0:
            self.MarketOrder(aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_previous_close <= spy_previous_average and spy_close > spy_average:
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20_000.0:
                quantity = floor(20_000.0 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.aapl_lot = quantity

    def _apply_splits(self, data):
        for split in data.Splits.Values:
            factor = float(split.SplitFactor)
            if factor <= 0:
                continue
            if split.Symbol == self.symbols["SPY"] and self.spy_lot:
                self.spy_lot = int(round(self.spy_lot / factor))
            elif split.Symbol == self.symbols["AAPL"] and self.aapl_lot:
                self.aapl_lot = int(round(self.aapl_lot / factor))

