class ParallelSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted strategy lots."""

    SPY_MOVING_AVERAGE_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma = SimpleMovingAverage(self.SPY_MOVING_AVERAGE_PERIOD)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_close = {symbol: None for symbol in self.symbols.values()}
        self.previous_spy_above_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = data.Bars
        all_present = all(symbol in bars for symbol in self.symbols.values())

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]
        spy_above_sma = None

        # Market-state quantities continue to consume every available bar, even
        # when an unrelated subscription is absent and trading must be skipped.
        for symbol in self.symbols.values():
            if symbol not in bars:
                continue

            bar = bars[symbol]
            prior_close = self.previous_close[symbol]

            if symbol == spy:
                self.spy_sma.Update(bar.EndTime, bar.Close)
                if self.spy_sma.IsReady:
                    spy_above_sma = bar.Close > self.spy_sma.Current.Value

            if symbol == aapl:
                if prior_close is not None:
                    if bar.Close < prior_close:
                        self.aapl_red_streak += 1
                    else:
                        self.aapl_red_streak = 0
                self.aapl_rsi.Update(bar.EndTime, bar.Close)

            self.previous_close[symbol] = bar.Close

        if not all_present:
            if spy_above_sma is not None:
                self.previous_spy_above_sma = spy_above_sma
            return

        spy_bar = bars[spy]
        aapl_bar = bars[aapl]

        # Sells are evaluated before buys. Each order quantity is restricted to
        # the shares attributed to its strategy's private lot.
        if self.strategy_a_shares > 0:
            crossed_below = (
                self.previous_spy_above_sma is True
                and spy_above_sma is False
            )
            if crossed_below:
                self.MarketOrder(spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            crossed_above = (
                self.previous_spy_above_sma is False
                and spy_above_sma is True
            )
            if crossed_above:
                target_value = self.Portfolio.TotalPortfolioValue * 0.40
                quantity = int(target_value // spy_bar.Close)
                if quantity > 0:
                    self.MarketOrder(spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_amount = 20_000
            if self.Portfolio.Cash >= cash_amount:
                quantity = int(cash_amount // aapl_bar.Close)
                if quantity > 0:
                    self.MarketOrder(aapl, quantity)
                    self.strategy_b_shares = quantity

        if spy_above_sma is not None:
            self.previous_spy_above_sma = spy_above_sma

