class IndependentDailyStrategies(QCAlgorithm):
    SMA_PERIOD = 20

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.SMA_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending = False
        self.aapl_pending = False

    def on_data(self, data: Slice):
        bars = data.bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if bars.contains_key(spy):
            self.spy_closes.append(float(bars[spy].close))

        if bars.contains_key(aapl):
            aapl_bar = bars[aapl]
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        if any(not bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        if len(self.spy_closes) < self.SMA_PERIOD + 1:
            return
        if not self.aapl_rsi.is_ready:
            return

        spy_bar = bars[spy]
        aapl_bar = bars[aapl]
        closes = list(self.spy_closes)
        previous_spy_close = closes[-2]
        current_spy_close = closes[-1]
        previous_spy_average = sum(closes[:-1]) / self.SMA_PERIOD
        current_spy_average = sum(closes[1:]) / self.SMA_PERIOD

        spy_crossed_above = (
            previous_spy_close <= previous_spy_average
            and current_spy_close > current_spy_average
        )
        spy_crossed_below = (
            previous_spy_close >= previous_spy_average
            and current_spy_close < current_spy_average
        )

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_pending and spy_crossed_below:
            self._submit(spy, -self.spy_lot, "spy_sell")

        if (
            self.aapl_lot > 0
            and not self.aapl_pending
            and self.aapl_rsi.current.value > 60
        ):
            self._submit(aapl, -self.aapl_lot, "aapl_sell")

        if self.spy_lot == 0 and not self.spy_pending and spy_crossed_above:
            quantity = floor(
                0.40 * float(self.portfolio.total_portfolio_value)
                / float(spy_bar.close)
            )
            if quantity > 0:
                self._submit(spy, quantity, "spy_buy")

        if (
            self.aapl_lot == 0
            and not self.aapl_pending
            and self.aapl_red_streak >= 3
            and float(self.portfolio.cash) >= 20_000
        ):
            quantity = floor(20_000 / float(aapl_bar.close))
            if quantity > 0:
                self._submit(aapl, quantity, "aapl_buy")

    def _submit(self, symbol, quantity, action):
        if action.startswith("spy_"):
            self.spy_pending = True
        else:
            self.aapl_pending = True
        self.market_order(symbol, quantity, tag=action)

    def on_order_event(self, order_event: OrderEvent):
        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None or order.tag not in (
            "spy_buy", "spy_sell", "aapl_buy", "aapl_sell"
        ):
            return
        action = order.tag

        fill_quantity = int(order_event.fill_quantity)
        if fill_quantity:
            if action == "spy_buy":
                self.spy_lot += fill_quantity
            elif action == "spy_sell":
                self.spy_lot = max(0, self.spy_lot + fill_quantity)
            elif action == "aapl_buy":
                self.aapl_lot += fill_quantity
            elif action == "aapl_sell":
                self.aapl_lot = max(0, self.aapl_lot + fill_quantity)

        if order_event.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
        ):
            if action.startswith("spy_"):
                self.spy_pending = False
            else:
                self.aapl_pending = False

