class ParallelSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD + 1)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(
            14, MovingAverageType.WILDERS
        )

        # Each strategy owns only the shares represented by its private lot.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_order = None
        self.strategy_b_order = None

    def on_data(self, data: Slice):
        # A day is usable only when all five subscribed equities have a bar.
        if any(symbol not in data.bars for symbol in self.symbols.values()):
            return

        spy_bar = data.bars[self.symbols["SPY"]]
        aapl_bar = data.bars[self.symbols["AAPL"]]

        self.spy_closes.append(float(spy_bar.close))

        aapl_close = float(aapl_bar.close)
        if self.aapl_previous_close is not None:
            if aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        self.aapl_previous_close = aapl_close
        self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self.strategy_a_order is None:
            if self._spy_crosses_below_average():
                self.strategy_a_order = self.market_order(
                    self.symbols["SPY"], -self.strategy_a_shares
                )

        if self.strategy_b_shares > 0 and self.strategy_b_order is None:
            if self.aapl_rsi.is_ready and self.aapl_rsi.current.value > 60:
                self.strategy_b_order = self.market_order(
                    self.symbols["AAPL"], -self.strategy_b_shares
                )

        if self.strategy_a_shares == 0 and self.strategy_a_order is None:
            if self._spy_crosses_above_average():
                quantity = floor(
                    0.40 * float(self.portfolio.total_portfolio_value)
                    / float(spy_bar.close)
                )
                if quantity > 0:
                    self.strategy_a_order = self.market_order(
                        self.symbols["SPY"], quantity
                    )

        if self.strategy_b_shares == 0 and self.strategy_b_order is None:
            if self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.strategy_b_order = self.market_order(
                        self.symbols["AAPL"], quantity
                    )

    def _spy_crosses_above_average(self):
        if len(self.spy_closes) < self.MOVING_AVERAGE_PERIOD + 1:
            return False
        closes = list(self.spy_closes)
        yesterday_average = sum(closes[:-1]) / self.MOVING_AVERAGE_PERIOD
        today_average = sum(closes[1:]) / self.MOVING_AVERAGE_PERIOD
        return closes[-2] <= yesterday_average and closes[-1] > today_average

    def _spy_crosses_below_average(self):
        if len(self.spy_closes) < self.MOVING_AVERAGE_PERIOD + 1:
            return False
        closes = list(self.spy_closes)
        yesterday_average = sum(closes[:-1]) / self.MOVING_AVERAGE_PERIOD
        today_average = sum(closes[1:]) / self.MOVING_AVERAGE_PERIOD
        return closes[-2] >= yesterday_average and closes[-1] < today_average

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.FILLED, OrderStatus.PARTIALLY_FILLED):
            if order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._clear_finished_order(order_event.order_id)
            return

        fill_quantity = int(order_event.fill_quantity)
        if self.strategy_a_order is not None and order_event.order_id == self.strategy_a_order.order_id:
            self.strategy_a_shares += fill_quantity
        elif self.strategy_b_order is not None and order_event.order_id == self.strategy_b_order.order_id:
            self.strategy_b_shares += fill_quantity

        if order_event.status == OrderStatus.FILLED:
            self._clear_finished_order(order_event.order_id)

    def _clear_finished_order(self, order_id):
        if self.strategy_a_order is not None and order_id == self.strategy_a_order.order_id:
            self.strategy_a_order = None
        if self.strategy_b_order is not None and order_id == self.strategy_b_order.order_id:
            self.strategy_b_order = None

