                bars[ticker] = data.bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if len(bars) != len(self.symbols):
            return

        self._run_strategy_a(float(spy_bar.close))
        self._run_strategy_b(float(aapl_bar.close))

    def _run_strategy_a(self, close):
        if len(self.spy_closes) < self.spy_closes.maxlen:
            return

        closes = list(self.spy_closes)
        previous_close = closes[-2]
        previous_average = sum(closes[-self.SPY_MOVING_AVERAGE_PERIOD - 1:-1]) / self.SPY_MOVING_AVERAGE_PERIOD
        current_average = sum(closes[-self.SPY_MOVING_AVERAGE_PERIOD:]) / self.SPY_MOVING_AVERAGE_PERIOD

        crossed_below = previous_close >= previous_average and close < current_average
        crossed_above = previous_close <= previous_average and close > current_average

        if self.spy_lot > 0:
            if crossed_below:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
            return

        if crossed_above:
            quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _run_strategy_b(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.current.value) > 60:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
            return

        if self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
            quantity = floor(20_000 / close)
            if quantity > 0:
                self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

