class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, close-of-day strategies with separately tracked lots."""

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ("SPY", "AAPL", "IBM", "BAC", "AIG")
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma = self.SMA(self.symbols["SPY"], 20, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"],
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.previous_closes = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        # These quantities are private strategy-lot ledgers, rather than the
        # aggregate security holdings maintained by the portfolio.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market state continues to advance for every ticker whose bar exists,
        # even on a day on which a missing subscription prevents evaluation.
        aapl = bars.get("AAPL")
        if aapl is not None:
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl.Close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = len(bars) == len(self.symbols)
        all_state_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_sma is not None
            and "SPY" in self.previous_closes
            and "AAPL" in self.previous_closes
        )

        if all_bars_present and all_state_ready and not self.IsWarmingUp:
            spy_close = bars["SPY"].Close
            previous_spy_close = self.previous_closes["SPY"]
            current_spy_sma = self.spy_sma.Current.Value

            # Sells are evaluated before buys.
            if self.strategy_a_shares > 0:
                crosses_below = (
                    previous_spy_close >= self.previous_spy_sma
                    and spy_close < current_spy_sma
                )
                if crosses_below:
                    self.MarketOrder(
                        self.symbols["SPY"], -self.strategy_a_shares
                    )
                    self.strategy_a_shares = 0

            if self.strategy_b_shares > 0:
                if self.aapl_rsi.Current.Value > 60:
                    self.MarketOrder(
                        self.symbols["AAPL"], -self.strategy_b_shares
                    )
                    self.strategy_b_shares = 0

            if self.strategy_a_shares == 0:
                crosses_above = (
                    previous_spy_close <= self.previous_spy_sma
                    and spy_close > current_spy_sma
                )
                if crosses_above:
                    quantity = self.CalculateOrderQuantity(
                        self.symbols["SPY"], 0.40
                    )
                    if quantity > 0:
                        self.MarketOrder(self.symbols["SPY"], quantity)
                        self.strategy_a_shares = quantity

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // bars["AAPL"].Close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.strategy_b_shares = quantity

        # Store each available bar independently so "yesterday" remains the
        # ticker's immediately preceding trading bar after skipped evaluations.
        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.Close
        if "SPY" in bars and self.spy_sma.IsReady:
            self.previous_spy_sma = self.spy_sma.Current.Value

