class ParallelSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.spy_previous_close = None
        self.spy_previous_average = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        self._apply_splits(data)

        spy_bar = data.bars.get(self.symbols["SPY"])
        aapl_bar = data.bars.get(self.symbols["AAPL"])

        spy_average = None
        spy_crosses_above = False
        spy_crosses_below = False
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_average = sum(self.spy_closes) / self.MOVING_AVERAGE_PERIOD
                if (
                    self.spy_previous_close is not None
                    and self.spy_previous_average is not None
                ):
                    spy_crosses_above = (
                        self.spy_previous_close <= self.spy_previous_average
                        and float(spy_bar.close) > spy_average
                    )
                    spy_crosses_below = (
                        self.spy_previous_close >= self.spy_previous_average
                        and float(spy_bar.close) < spy_average
                    )

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(
                IndicatorDataPoint(aapl_bar.end_time, aapl_close)
            )

        all_bars_present = all(
            data.bars.get(symbol) is not None for symbol in self.symbols.values()
        )

        if all_bars_present:
            # Every strategy's sell is evaluated before either strategy's buy.
            if self.strategy_a_shares > 0 and spy_crosses_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi.is_ready
                and self.aapl_rsi.current.value > 60
            ):
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0 and spy_crosses_above:
                quantity = floor(
                    0.40 * float(self.portfolio.total_portfolio_value)
                    / float(spy_bar.close)
                )
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

            if (
                self.strategy_b_shares == 0
                and self.aapl_rsi.is_ready
                and self.aapl_red_streak >= 3
                and float(self.portfolio.cash) >= 20_000
            ):
                quantity = floor(20_000 / float(aapl_bar.close))
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

        if spy_bar is not None:
            self.spy_previous_close = float(spy_bar.close)
            self.spy_previous_average = spy_average
        if aapl_bar is not None:
            self.aapl_previous_close = float(aapl_bar.close)

    def _apply_splits(self, data: Slice):
        spy_split = data.splits.get(self.symbols["SPY"])
        if spy_split is not None and self.strategy_a_shares > 0:
            self.strategy_a_shares = int(
                round(self.strategy_a_shares / float(spy_split.split_factor))
            )

        aapl_split = data.splits.get(self.symbols["AAPL"])
        if aapl_split is not None and self.strategy_b_shares > 0:
            self.strategy_b_shares = int(
                round(self.strategy_b_shares / float(aapl_split.split_factor))
            )

from AlgorithmImports import *
from collections import deque
import math


class ParallelSpyAaplStrategies(QCAlgorithm):
    MOVING_AVERAGE_PERIOD = 20
    RSI_PERIOD = 14

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=self.MOVING_AVERAGE_PERIOD)
        self.previous_spy_close = None
        self.previous_spy_average = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_seed_gains = []
        self.aapl_seed_losses = []
        self.aapl_rsi = None

    def on_data(self, data: Slice):
        bars = data.bars

        if bars.contains_key(self.spy):
            spy_close = float(bars[self.spy].close)
            self.spy_closes.append(spy_close)
            spy_average = None
            if len(self.spy_closes) == self.MOVING_AVERAGE_PERIOD:
                spy_average = sum(self.spy_closes) / self.MOVING_AVERAGE_PERIOD
        else:
            spy_close = None
            spy_average = None

        if bars.contains_key(self.aapl):
            aapl_close = float(bars[self.aapl].close)
            self._update_aapl_state(aapl_close)
        else:
            aapl_close = None

        complete_slice = all(bars.contains_key(symbol) for symbol in self.symbols)

        if complete_slice:
            self._run_spy_strategy(spy_close, spy_average)
            self._run_aapl_strategy(aapl_close)

        if spy_close is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_average = spy_average

    def _update_aapl_state(self, close):
        if self.previous_aapl_close is None:
            self.previous_aapl_close = close
            return

        change = close - self.previous_aapl_close
        if change < 0:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_average_gain is None:
            self.aapl_seed_gains.append(gain)
            self.aapl_seed_losses.append(loss)
            if len(self.aapl_seed_gains) == self.RSI_PERIOD:
                self.aapl_average_gain = sum(self.aapl_seed_gains) / self.RSI_PERIOD
                self.aapl_average_loss = sum(self.aapl_seed_losses) / self.RSI_PERIOD
                self.aapl_rsi = self._calculate_rsi()
        else:
            self.aapl_average_gain = (
                self.aapl_average_gain * (self.RSI_PERIOD - 1) + gain
            ) / self.RSI_PERIOD
            self.aapl_average_loss = (
                self.aapl_average_loss * (self.RSI_PERIOD - 1) + loss
            ) / self.RSI_PERIOD
            self.aapl_rsi = self._calculate_rsi()

        self.previous_aapl_close = close

    def _calculate_rsi(self):
        if self.aapl_average_loss == 0:
            return 100.0 if self.aapl_average_gain > 0 else 50.0
        relative_strength = self.aapl_average_gain / self.aapl_average_loss
        return 100.0 - 100.0 / (1.0 + relative_strength)

    def _run_spy_strategy(self, close, moving_average):
        if (
            moving_average is None
            or self.previous_spy_close is None
            or self.previous_spy_average is None
        ):
            return

        quantity = int(self.portfolio[self.spy].quantity)
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_average
            and close < moving_average
        )
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_average
            and close > moving_average
        )

        if quantity > 0 and crosses_below:
            self.market_order(self.spy, -quantity)
            quantity = 0

        if quantity == 0 and crosses_above:
            target_quantity = math.floor(
                0.40 * float(self.portfolio.total_portfolio_value) / close
            )
            if target_quantity > 0:
                self.market_order(self.spy, target_quantity)

    def _run_aapl_strategy(self, close):
        if self.aapl_rsi is None:
            return

        quantity = int(self.portfolio[self.aapl].quantity)

        if quantity > 0 and self.aapl_rsi > 60:
            self.market_order(self.aapl, -quantity)
            quantity = 0

        if quantity == 0 and self.aapl_red_streak >= 3:
            allocation = 20_000
            if float(self.portfolio.cash) >= allocation:
                buy_quantity = math.floor(allocation / close)
                if buy_quantity > 0:
                    self.market_order(self.aapl, buy_quantity)
